from pathlib import Path
p=Path('src/client/GroupChatModelSettings.tsx');s=p.read_text(encoding='utf-8-sig')
s=s.replace("function SearchableModelPicker({label,value,catalog,allowDefault=false,onChange}:{label:string;value:Model;catalog:Catalog;allowDefault?:boolean;onChange:(m:Model)=>void}){", "function SearchableModelPicker({label,value,catalog,allowDefault=false,onChange,onDeleteRecent}:{label:string;value:Model;catalog:Catalog;allowDefault?:boolean;onChange:(m:Model)=>void;onDeleteRecent?:(m:Model)=>void}){")
s=s.replace("{catalog.recent.filter(m=>m.provider&&m.model).map((m,i)=><button type=\"button\" className=\"gc-model-option gc-model-recent\" role=\"option\" key={`recent-${i}`} onClick={()=>choose(m)}><span>{labelFor(m)}</span><small>最近使用</small></button>)}", "{catalog.recent.filter(m=>m.provider&&m.model).map((m,i)=><div className=\"gc-model-recent-row\" key={`recent-${i}`}><button type=\"button\" className=\"gc-model-option gc-model-recent\" role=\"option\" onClick={()=>choose(m)}><span>{labelFor(m)}</span><small>最近使用</small></button><button type=\"button\" className=\"gc-model-delete\" aria-label={`删除最近模型 ${labelFor(m)}`} title=\"删除这个最近模型\" onClick={e=>{e.preventDefault();e.stopPropagation();onDeleteRecent?.(m)}}>×</button></div>)}")
