s=s.replace("  useEffect(()=>{const abort=new AbortController();fetch('/dsh-group-chat/api/models',{signal:abort.signal}).then(async r=>{if(!r.ok)throw Error('目录加载失败');return r.json()}).then(data=>{setCatalog(data);setStatus(data.groups.some((g:Catalog['groups'][number])=>g.error)?'部分目录加载失败；仍可手动填写模型 ID。':'')}).catch(e=>{if(!abort.signal.aborted)setStatus(e.message+'，可手动输入或重试。')});return()=>abort.abort()},[reload])", "  useEffect(()=>{const abort=new AbortController();fetch('/dsh-group-chat/api/models',{signal:abort.signal}).then(async r=>{if(!r.ok)throw Error('目录加载失败');return r.json()}).then(data=>{setCatalog(data);setStatus(data.groups.some((g:Catalog['groups'][number])=>g.error)?'部分目录加载失败；仍可手动填写模型 ID。':'')}).catch(e=>{if(!abort.signal.aborted)setStatus(e.message+'，可手动输入或重试。')});return()=>abort.abort()},[reload])\n  const deleteRecent=async(model:Model)=>{\n    setCatalog(prev=>({...prev,recent:prev.recent.filter(m=>m.provider!==model.provider||m.model!==model.model)}))\n    try{\n      const response=await fetch('/dsh-group-chat/api/models/recent/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(model)})\n      const data=await response.json()\n      if(!response.ok||!data.success)throw Error(data.error||'删除失败')\n      setCatalog(prev=>({...prev,recent:data.recent||[]}))\n    }catch(e){setStatus(e instanceof Error?e.message:String(e));setReload(v=>v+1)}\n  }")
s=s.replace(".gc-model-list{max-height:260px;overflow:auto;display:flex;flex-direction:column;gap:2px}.gc-model-option{display:flex!important;flex-direction:column;align-items:flex-start;width:100%;text-align:left;margin:0!important;background:transparent!important;border:0!important}", ".gc-model-list{max-height:260px;overflow:auto;display:flex;flex-direction:column;gap:2px}.gc-model-recent-row{display:grid;grid-template-columns:1fr 28px;align-items:stretch;border-radius:10px}.gc-model-recent-row:hover{background:var(--dsw-alias-bg-layer-2,#2b2b31)}.gc-model-option{display:flex!important;flex-direction:column;align-items:flex-start;width:100%;text-align:left;margin:0!important;background:transparent!important;border:0!important}")
