s=s.replace('<SearchableModelPicker label="主模型" value={primary} catalog={catalog} allowDefault onChange={onPrimary}/>', '<SearchableModelPicker label="主模型" value={primary} catalog={catalog} allowDefault onChange={onPrimary} onDeleteRecent={deleteRecent}/>')
